#endif
      use iso_c_binding
      use hipfort_hipblas_enums
      use hipfort_enums
      implicit none
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: hipblasGemmEx_
      type(c_ptr),value :: handle
