      type(c_ptr),value :: alpha
      type(c_ptr),value :: A
      integer(kind(HIP_R_32F)),value :: aType
      integer(c_int),value :: lda
      type(c_ptr),value :: B
      integer(kind(HIP_R_32F)),value :: bType
      integer(c_int),value :: ldb
